  if(['orbit','sun','coil','gears'].includes(morph))for(let j=0;j<36;j++){const a=j*TAU/36;d.ell(Math.cos(a)*.23,.3+Math.sin(a)*.23,.18,.02,.021,.023,T);if(j%6===0)d.glow(Math.cos(a)*.24,.3+Math.sin(a)*.24,.20,A);}
