const entityBeforeCatalog=makeEntity;makeEntity=function(key,pos,opts={}){const e=entityBeforeCatalog(key,pos,opts);if(e.elite&&!e.passive&&!e.boss){const names=Object.keys(ELITE_TYPES),id=opts.eliteType&&ELITE_TYPES[opts.eliteType]?opts.eliteType:names[contentHash(key+'|'+e.eid+'|'+G.levelSeed)%names.length],profile=ELITE_TYPES[id];e.eliteType=id;e.ability=profile.ability;e.name=profile.name+' · '+e.spec.name;e.hp=e.maxhp*=profile.hp;const plate=morphologyArt(key,profile.morph,'body',scene);attachProto(plate,e.rig.nodes.torsoN||e.rig.nodes.body,e.rig.parts);if(e.rig.articulated){const savedSeed=SEED;const it=makeItem('chest',Math.max(2,G.depth*2),3,Object.keys(ARMOR_SETS)[contentHash(id)%setRows.length]);SEED=savedSeed;attachProto(armorModel(it,scene,'shoulder'),e.rig.nodes.shL,e.rig.parts);attachProto(armorModel(it,scene,'shoulder'),e.rig.nodes.shR,e.rig.parts);}}else e.ability=e.spec.ability||null;e.specialCd=3+(contentHash(key)%50)/10;e.specialCount=0;return e;};
const detailBeforeCatalog=showDetail;showDetail=function(it){detailBeforeCatalog(it);if(it?.armorSet&&ARMOR_SETS[it.armorSet]){const set=ARMOR_SETS[it.armorSet],label={hp:'health',armor:'armor',ms:'% movement speed',spd:'% attack speed',crit:'% critical chance',critdmg:'% critical damage',ls:'% life steal',stamr:'% stamina recovery',dmg:'damage'}[set.bonus];$('dInfo').insertAdjacentHTML('beforeend','<div class="setNote"><b>'+escaped(set.name)+' collection</b><p>3 pieces: +'+set.value+' '+label+'<br>5 pieces: +'+set.value*2+' '+label+'</p></div>');}};
