// Optimize aggregate equipment score including three/five-piece bonuses.
function loadoutScore(gear){let score=0,counts={};const weights=POWER_WEIGHTS;for(const it of Object.values(gear))if(it){score+=it.score;if(it.armorSet)counts[it.armorSet]=(counts[it.armorSet]||0)+1;}for(const [key,n]of Object.entries(counts)){const set=ARMOR_SETS[key];if(set&&n>=3)score+=set.value*(n>=5?2:1)*weights[set.bonus];}return score;}
autoEquip=function(){const p=player,owned=[...new Map([...Object.values(p.gear),...p.bag].filter(Boolean).map(it=>[it.id,it])).values()],slots=SLOTS.filter(s=>s!=='weapon');let best={...p.gear},score=loadoutScore(best);const top=(slot,set,hands)=>owned.filter(it=>it.slot===slot&&(!set||it.armorSet===set)&&(!hands||it.hands===hands)).sort((a,b)=>b.score-a.score)[0]||null;const evaluate=gear=>{if(gear.weapon?.hands===2)gear.offhand=null;const s=loadoutScore(gear);if(s>score+.001){score=s;best={...gear};}};
 for(const weapon of[top('weapon',null,1),top('weapon',null,2),p.gear.weapon].filter(Boolean)){const raw={weapon};for(const s of slots)raw[s]=s==='offhand'&&weapon.hands===2?null:top(s);evaluate({...raw});for(const key of Object.keys(ARMOR_SETS)){const choices=slots.filter(s=>!(s==='offhand'&&weapon.hands===2)&&top(s,key));for(const count of[3,5]){if(choices.length<count)continue;const visit=(i,taken,gear)=>{if(taken===count){evaluate(gear);return;}for(let j=i;j<=choices.length-(count-taken);j++){const slot=choices[j];visit(j+1,taken+1,{...gear,[slot]:top(slot,key)});}};visit(0,0,{...raw});}}}
 const changed=SLOTS.filter(s=>p.gear[s]!==best[s]).length;if(changed){const equipped=new Set(Object.values(best).filter(Boolean).map(it=>it.id));p.gear=best;p.bag=owned.filter(it=>!equipped.has(it.id));computeStats(p);renderEquip(p);selected=null;refreshInv();toast('Equipped '+changed+' pieces · set bonuses included','#b1d6ac');}else toast('Already wearing your best available combination','#a4b3bb');};
